/**
 * @param {number[]} nums
 * @return {number}
 */
var longestBalanced = function(nums) {
    const n = nums.length;
    let res = 0;

    for (let i = 0; i < n; i++) {
        const odd = new Set();
        const even = new Set();

        for (let j = i; j < n; j++) {
            if (nums[j] & 1) {
                odd.add(nums[j]);
            } else {
                even.add(nums[j]);
            }

            if (odd.size === even.size) {
                res = Math.max(res, j - i + 1);
            }
        }
    }

    return res;
};
